@* TemplatedList.razor: the owner keeps the state and calls the caller's template *@
@foreach (var item in Items) { @RowTemplate(item) }

@code {
    [Parameter, EditorRequired] public RenderFragment<TItem> RowTemplate { get; set; } = default!;
    [Parameter, EditorRequired] public IReadOnlyList<TItem> Items { get; set; } = default!;
}
@* usage: <TemplatedList Items="pets" TItem="Pet"> <RowTemplate>@(pet => <p>@pet.Name</p>)</RowTemplate> </TemplatedList> *@

